import React, { useEffect, useState } from "react";
import axios from "axios";
import "./FAQ.css";

const FAQ = () => {
  const [faqs, setFaqs] = useState([]);
  const [loading, setLoading] = useState(true);

  const [serviceForm, setServiceForm] = useState({
    name: "",
    email: "",
    message: "",
  });

  useEffect(() => {
    fetchFAQs();
  }, []);

  const fetchFAQs = async () => {
    try {
      const { data } = await axios.get("/api/v1/faqs");

      if (data.success) {
        setFaqs(data.faqs);
      }
    } catch (error) {
      console.error("Error fetching FAQs:", error);
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    setServiceForm({
      ...serviceForm,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    alert("Customer service request submitted.");

    setServiceForm({
      name: "",
      email: "",
      message: "",
    });
  };

  return (
    <div className="faq-page">

      {/* FAQ Section */}

      <div className="faq-section">

        <h1>Frequently Asked Questions</h1>

        <div className="quick-help">
          <h3>Quick Help</h3>

          <button>Orders</button>{" "}
          <button>Payments</button>{" "}
          <button>Shipping</button>{" "}
          <button>Returns</button>
        </div>

        <br />

        {loading ? (
          <h3>Loading FAQs...</h3>
        ) : faqs.length === 0 ? (
          <h3>No FAQs Available</h3>
        ) : (
          <div className="faq-category">
            {faqs.map((faq) => (
              <details key={faq._id}>
                <summary>
                  <button
                    style={{
                      width: "100%",
                      textAlign: "left",
                      border: "none",
                      background: "white",
                      padding: "12px",
                      cursor: "pointer",
                    }}
                  >
                    {faq.question}
                  </button>
                </summary>

                <div
                  style={{
                    padding: "12px",
                    background: "#fafafa",
                  }}
                >
                  <p>{faq.answer}</p>

                  {faq.category && (
                    <small>
                      <strong>Category:</strong> {faq.category}
                    </small>
                  )}
                </div>
              </details>
            ))}
          </div>
        )}
      </div>

      {/* Customer Service */}

      <div className="service-section">

        <h2>Contact Customer Service</h2>

        <form onSubmit={handleSubmit}>

          <label>Name</label>

          <input
            type="text"
            name="name"
            value={serviceForm.name}
            onChange={handleChange}
            required
          />

          <br />
          <br />

          <label>Email</label>

          <input
            type="email"
            name="email"
            value={serviceForm.email}
            onChange={handleChange}
            required
          />

          <br />
          <br />

          <label>Message</label>

          <textarea
            rows="5"
            name="message"
            value={serviceForm.message}
            onChange={handleChange}
            required
          />

          <br />
          <br />

          <button type="submit">
            Submit Request
          </button>

        </form>
      </div>

    </div>
  );
};

export default FAQ;
